pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 a1, uint256 a2) internal {
        a1 = bound(a1, 0, 1000000000000000000000000000000);
        a2 = bound(a2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a1 > 0 && a2 > 0 && a2 != a1);
        vm.assume(address(this).balance >= a1 + a2);
        try c.deposit{value: a1}() {} catch { return; }
        try c.deposit{value: a2}() {} catch { return; }
        bool ok;
        try c.withdraw(a1 + a2) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }

    function testFuzz_run(uint256 a1, uint256 a2) public {
        _run(a1, a2);
    }

    receive() external payable {}
}
